from itertools import combinations
rows=['0110110','1111110','0110100','0011100']
S={(r,c) for r,line in enumerate(rows) for c,x in enumerate(line) if x=='1'}
shapes=[]
# square or L subset of each 2x2
for r in range(3):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if block<=S: shapes.append(('Q',block,None))
  for miss in block:
   shp=block-{miss}
   if shp<=S: shapes.append(('L',shp,miss))
solutions=[]
def rec(rem, qs, tiles):
 if not rem:
  if qs==1 and len(tiles)==5: solutions.append(tiles)
  return
 if qs>1 or len(tiles)>=5:return
 cell=min(rem)
 for typ,shp,miss in shapes:
  if cell in shp and shp<=rem:
   if typ=='Q' and qs: continue
   rec(rem-shp,qs+(typ=='Q'),tiles+[(typ,shp,miss)])
rec(S,0,[])
print('solutions',len(solutions),'S',len(S))
for sol in solutions[:20]:
 print([(t,sorted((r+1,c+1) for r,c in s), (m[0]+1,m[1]+1) if m else None) for t,s,m in sol])
